91	<main>
92	<h1>OpenSurvey</h1>
93	<p>问卷调查与反馈管理</p>
94	<div id="app"></div>
95	<p class="muted"><a href="/api/surveys">问卷列表接口</a> · <a href="/health">服务状态</a></p>
96	</main>
97	<script>
98	"use strict";
99	const app = document.getElementById("app");
100	
101	// 每次进入一个页面都开启新一代视图：切换首页/详情/编辑、重新进入同一份问卷、
102	// 重试加载以及浏览器前进/后退都会使代数递增。较早一代页面发起的请求再晚
103	// 返回也必须丢弃，不能覆盖用户当前所在页面。
104	let activeView = 0;
105	
106	// 首尾裁剪必须与接口（Python str.strip()）逐字符一致，网页校验、提交内容与
107	// “是否还有未保存修改”的比较才能表达同一份文本含义。JS 原生 trim() 的字符集
108	// 恰好不同：它会裁掉 U+FEFF（接口保留该字符），却不裁 U+0085 与 U+001C–
109	// U+001F（接口会把它们当空白裁掉）。这里显式列出接口会裁的 29 个字符，
110	// U+FEFF 刻意不在其中；内部字符（含内部换行）一律不动。说明字段从不裁剪。
111	const API_TRIM_CLASS =
112	  "\\t\\n\\v\\f\\r\\x1c-\\x1f\\x20\\u0085\\u00a0\\u1680" +
113	  "\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000";
114	const apiTrimRe = new RegExp(
115	  "^[" + API_TRIM_CLASS + "]+|[" + API_TRIM_CLASS + "]+$", "g");
116	function apiTrim(value) { return value.replace(apiTrimRe, ""); }
117	
118	// 换行归一化：接口会原样保留文本内部的回车换行（CRLF，\r\n）、单独回车
119	// （CR，\r）与换行（LF，\n），但这些值赋给 textarea 后会被浏览器立即统一
120	// 成 LF（实测在赋值给 .value 的那一刻即发生）。因此编辑页必须在把原稿送进
121	// 输入框之前记录原始字符串，保存时再按“可见内容是否改变”决定还原原稿还是
122	// 采用当前输入；比较一律基于归一化为 LF 的文本，使三种换行在编辑框里的同
123	// 一份可见内容被视为“没有改变”。
124	function normalizeNL(value) { return value.replace(/\r\n|\r|\n/g, "\n"); }
125	
126	// 仅编辑模式使用：输入框元素 -> 打开编辑页时该字段从接口读到的原始字符串。
127	// 用 WeakMap 是为了让随题目/选项删除而移除的元素连同记录一起被回收，绝不
128	// 需要手工清理，也不会把已删除行的原文错配到后来顶上来的另一行。新建模式
129	// 下不写入任何记录。
130	const origMap = new WeakMap();
131	function rememberOriginal(el, raw) { origMap.set(el, String(raw)); }
132	
133	// 计算一个文本字段“实际要保存”的字符串：
134	// - 编辑模式且该字段可见内容与打开时一致：还原为原稿，保留原始 CRLF/CR/LF；
135	// - 其余情况（真正修改过，或新建模式）：采用输入框当前文本（浏览器统一为 LF）。
136	// 比较规则与“判断文字是否改变”的既有规则一致：trimFields 为真时（问卷标题、
137	// 题目标题、选项）首尾空白不参与比较，因此只增删首尾空白也算未改变、仍还原
138	// 原稿（原稿内部的 CRLF/CR 不会因此被 LF 覆盖）；说明字段不裁剪，逐字符比较。
139	function resolveFieldValue(el, {trimFields = false} = {}) {
140	  const current = el.value;
141	  const original = origMap.get(el);
142	  if (original !== undefined) {
143	    const a = trimFields ? apiTrim(normalizeNL(current)) : normalizeNL(current);
144	    const b = trimFields ? apiTrim(normalizeNL(original)) : normalizeNL(original);
145	    if (a === b) return original;
146	  }
147	  return current;
148	}
149	
150	function h(tag, attrs, ...children) {
151	  const el = document.createElement(tag);
152	  if (attrs) for (const [k, v] of Object.entries(attrs)) {
153	    if (v === null || v === undefined) continue;
154	    if (k === "class") el.className = v;
155	    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
156	    else el.setAttribute(k, v);
157	  }
158	  for (const child of children.flat()) {
159	    if (child === null || child === undefined) continue;
160	    el.append(child.nodeType ? child : document.createTextNode(String(child)));
161	  }
162	  return el;
163	}
164	
165	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
166	
167	function buildSurveyForm(existing, hooks, view) {
168	  // 新建表单首次创建成功且等待期间仍有未保存修改时，会就地转为“编辑刚创建
169	  // 的那份草稿”，因此 mode 允许从 create 切换为 edit。
170	  let mode = existing ? "edit" : "create";
171	
172	  // 表单当前正在编辑的草稿编号：编辑模式一开始就有；新建模式只在首次创建
173	  // 成功后才拿到。拿到编号之后，这份表单继续保存时一律 PUT 同一编号，不
174	  // 能再 POST 出第二份问卷。
175	  let surveyId = existing ? existing.id : null;
176	
177	  const banner = h("div", {class: "banner", id: "form-banner"});
178	  banner.hidden = true;
179	
180	  // 保存结果的状态条：成功保存与“仍有未保存修改”必须分开展示，不能只给
181	  // 一条笼统的“保存成功”。新建模式首次保存成功且等待期间没有新改动时直接
182	  // 进入详情（状态条不可见）；等待期间又有改动时则与编辑模式共用本状态条。
183	  const statusBar = h("div", {class: "save-status", id: "save-status", role: "status"});
184	  statusBar.hidden = true;
185	
186	  const titleInput = h("textarea", {id: "survey-title", rows: "1", class: "grow",
187	    maxlength: "200", placeholder: "请输入问卷标题（可含换行）"});
188	  const titleErr = h("p", {class: "field-err", id: "title-err"});
189	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
190	  const qBox = h("div", {id: "questions"});
191	  const qErr = h("p", {class: "field-err", id: "questions-err"});
192	
193	  function renumber() {
194	    const cards = qBox.querySelectorAll(".q-card");
195	    cards.forEach((card, i) => {
196	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
197	      card.querySelectorAll(".opt-row").forEach((row, j) => {
198	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
199	      });
200	    });
201	  }
202	
203	  // textarea 的高度随内容变化：单行内容外观与原输入框一致，出现内部换行时
204	  // 自动增高，让换行真实可见、可编辑，而不是被折叠或截断。
205	  function autoGrow(el) {
206	    el.style.height = "auto";
207	    el.style.height = `${el.scrollHeight}px`;
208	  }
209	  // 预填值时元素可能还没挂到文档上（scrollHeight 为 0），延到下一帧布局后再量。
210	  function scheduleGrow(el) { requestAnimationFrame(() => autoGrow(el)); }
211	
212	  function optionRow(value) {
213	    const text = h("textarea", {rows: "1", class: "opt-text grow", placeholder: "选项内容（可含换行）"});
214	    text.addEventListener("input", () => autoGrow(text));
215	    if (value !== undefined && value !== null) {
216	      // 必须在写入 .value 之前记录原稿：赋值一旦发生，CRLF/CR 就已被浏览器
217	      // 归一化成 LF，之后再读 text.value 也拿不回原始换行形式。
218	      if (mode === "edit") rememberOriginal(text, value);
219	      text.value = value; scheduleGrow(text);
220	    }
221	    const row = h("div", {class: "opt-row"},
222	      h("span", {class: "opt-index"}, "选项"),
223	      text,
224	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
225	    );
226	    return row;
227	  }
228	
229	  function addQuestion(type, prefill) {
230	    const isChoice = type === "single_choice";
231	    const options = h("div", {class: "options"});
232	    const card = h("div", {class: "card q-card", "data-type": type},
233	      h("div", {class: "q-head"},
234	        h("span", {class: "q-index"}, "第 N 题"),
235	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
236	        h("label", {class: "req"},
237	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
238	        h("span", {class: "spacer"}),
239	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
240	      ),
241	      h("textarea", {rows: "1", class: "q-title grow", placeholder: "题目标题（可含换行）"}),
242	      h("p", {class: "field-err q-title-err"})
243	    );
244	    if (isChoice) {
245	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
246	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
247	      else options.append(optionRow(), optionRow());
248	      card.append(
249	        options,
250	        h("p", {class: "field-err opt-err"}),
251	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
252	      );
253	      card.querySelector(".add-opt").addEventListener("click", () => {
254	        options.append(optionRow());
255	        renumber();
256	        options.querySelector(".opt-row:last-child .opt-text").focus();
257	      });
258	    }
259	    const qTitleEl = card.querySelector(".q-title");
260	    qTitleEl.addEventListener("input", () => autoGrow(qTitleEl));
261	    if (prefill) {
262	      // 与选项同理：在 .value 赋值（会把 CRLF/CR 归一化成 LF）之前先记住原稿。
263	      if (mode === "edit" && prefill.title != null) rememberOriginal(qTitleEl, prefill.title);
264	      qTitleEl.value = prefill.title != null ? prefill.title : "";
265	      card.querySelector(".q-required").checked = !!prefill.required;
266	    }
267	    scheduleGrow(qTitleEl);
268	    qBox.append(card);
269	    renumber();
270	    if (!prefill) qTitleEl.focus();
271	    return card;
272	  }
273	
274	  function clearErrors() {
275	    banner.hidden = true;
276	    banner.replaceChildren();
277	    titleErr.textContent = "";
278	    qErr.textContent = "";
279	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
280	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
281	  }
282	
283	  function hideSaveStatus() {
284	    statusBar.hidden = true;
285	    statusBar.replaceChildren();
286	  }
287	
288	  // 保存成功后：绿色块只陈述“刚才提交的内容已保存”；若等待期间又有修改，
289	  // 再追加一块黄色“当前还有未保存的修改”。两者同时出现、含义互不混淆。
290	  function renderSaveStatus(dirty) {
291	    statusBar.replaceChildren(
292	      h("div", {class: "save-note saved", id: "save-note-saved"},
293	        h("strong", null, "已保存：刚才提交的内容已保存到服务器。")),
294	      dirty
295	        ? h("div", {class: "save-note dirty", id: "save-note-dirty"},
296	            h("strong", null,
297	              "当前还有未保存的修改：页面内容在点击保存后又被改动（等待结果期间的修改不会自动补交）。可继续编辑，并再次点击“保存修改”。"))
298	        : null
299	    );
300	    statusBar.hidden = false;
301	  }
302	
303	  // 一次保存进行中：保存按钮禁用并明确显示“正在保存…”，状态条显示等待提示。
304	  // 在请求有明确结果前，重复点击按钮或用键盘再次提交都不会追加请求，也不会
305	  // 清掉等待提示。等待期间标题、说明、题目、选项、必填与增删操作全部可用。
306	  let saving = false;
307	  function setSavingUI() {
308	    submitButton.disabled = true;
309	    submitButton.textContent = "正在保存…";
310	    statusBar.replaceChildren(
311	      h("div", {class: "save-note saving", id: "save-note-saving", role: "status"},
312	        h("strong", null, "正在保存：正在等待本次保存的结果，请稍候。等待期间仍可继续编辑，这些改动不会自动追加到本次提交。"))
313	    );
314	    statusBar.hidden = false;
315	  }
316	  function resetSaveButton() {
317	    submitButton.disabled = false;
318	    submitButton.textContent = submitButton.getAttribute("data-label");
319	  }
320	
321	  // 整份草稿的唯一整理入口：保存时提交的内容、保存前的校验、编辑页判断
322	  // “等待保存期间是否又有修改”都从这里取数，规则只维护这一份。标题/题目
323	  // 标题/选项只按接口规则（apiTrim，与 Python strip 一致）去掉首尾空白，
324	  // 说明与内部换行原样保留；题目与选项按页面当前顺序记录，必填勾选原样。
325	  // 编辑模式下未改动的字段（含“改过又恢复”）由 resolveFieldValue 还原为
326	  // 打开时从接口读到的原稿，使内部 CRLF/CR/LF 不被浏览器的换行归一化改写；
327	  // 真正改动的字段与新建模式一律采用当前输入（浏览器中只会是 LF）。
328	  // 每次调用都返回新建的独立对象（后续输入不会改变已返回的快照），可直接
329	  // 做整体相等比较：改过又恢复原值时结构相同，不会被当成有未保存修改。
330	  function readDraft() {
331	    return {
332	      title: apiTrim(resolveFieldValue(titleInput, {trimFields: true})),
333	      description: resolveFieldValue(descArea),
334	      questions: [...qBox.querySelectorAll(".q-card")].map(card => ({
335	        type: card.dataset.type,
336	        title: apiTrim(resolveFieldValue(card.querySelector(".q-title"), {trimFields: true})),
337	        required: card.querySelector(".q-required").checked,
338	        options: [...card.querySelectorAll(".opt-text")]
339	          .map(el => apiTrim(resolveFieldValue(el, {trimFields: true})))
340	      }))
341	    };
342	  }
343	
344	  function sameState(a, b) { return JSON.stringify(a) === JSON.stringify(b); }
345	
346	  function showBanner(items) {
347	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
348	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
349	    banner.hidden = false;
350	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
351	  }
352	
353	  const actionButtons = [
354	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
355	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
356	    h("span", {class: "spacer"})
357	  ];
358	  if (mode === "edit") {
