469	      problems.push({el: qBox, msg: "问卷至少需要保留一道题，请先添加题目。"});
470	    }
471	
472	    // 校验针对整理后的草稿内容（空标题、空选项、同题重复选项都按裁剪后的值
473	    // 判断），错误标记仍落在对应的页面输入框上；输入框原文保持不动。
474	    cards.forEach((card, i) => {
475	      const loc = `第 ${i + 1} 题`;
476	      const question = draft.questions[i];
477	      const titleEl = card.querySelector(".q-title");
478	      if (!question.title) {
479	        titleEl.classList.add("invalid");
480	        card.querySelector(".q-title-err").textContent = `${loc}：题目标题不能为空。`;
481	        problems.push({el: titleEl, msg: `${loc}：题目标题不能为空。`});
482	      }
483	      if (question.type === "single_choice") {
484	        const optInputs = [...card.querySelectorAll(".opt-text")];
485	        const optErr = card.querySelector(".opt-err");
486	        const seen = new Set();
487	        question.options.forEach((val, j) => {
488	          if (!val) {
489	            optInputs[j].classList.add("invalid");
490	            optErr.textContent = `${loc}：第 ${j + 1} 个选项不能为空。`;
491	            problems.push({el: optInputs[j], msg: `${loc}：第 ${j + 1} 个选项不能为空。`});
492	          } else if (seen.has(val)) {
493	            optInputs[j].classList.add("invalid");
494	            optErr.textContent = `${loc}：选项“${val}”与同题其他选项重复。`;
495	            problems.push({el: optInputs[j], msg: `${loc}：选项“${val}”重复。`});
496	          }
497	          seen.add(val);
498	        });
499	        if (question.options.length < 2) {
500	          optErr.textContent = `${loc}：单选题至少需要两个选项。`;
501	          problems.push({el: card.querySelector(".add-opt"), msg: `${loc}：单选题至少需要两个选项。`});
502	        }
503	      }
504	    });
505	
506	    if (problems.length) {
507	      showBanner(problems);
508	      return;
509	    }
510	    // 校验通过、请求即将发出：此后到拿到明确结果前只能有这一次保存进行中。
511	    // 纯客户端校验拒绝不会走到这里，因此不会留下等待状态。
512	    saving = true;
513	    setSavingUI();
