515	    // 提交内容就是这份草稿本身：文本题不带 options（接口接受省略或空数组），
516	    // 单选题按整理后的选项内容与顺序提交。
517	    const payload = {
518	      title: draft.title,
519	      description: draft.description,
520	      questions: draft.questions.map(q => q.type === "single_choice"
521	        ? {type: q.type, title: q.title, required: q.required, options: q.options}
522	        : {type: q.type, title: q.title, required: q.required})
523	    };
524	    // 点击保存这一刻的整份表单快照：这次请求只代表这份内容。readDraft 返回的
525	    // 是独立对象，等待期间的后续输入不会改变它；成功返回后拿它与重新读取的
