527	    const submittedState = draft;
528	    // 新建表单在首次创建成功之前没有编号，走 POST；一旦创建成功，这份表单就
529	    // 绑定到新编号，此后再保存一律 PUT 同一编号，绝不新增第二份问卷。
530	    const creating = surveyId === null;
531	    const endpoint = creating ? "/api/surveys" : `/api/surveys/${surveyId}`;
532	    // 这次保存只属于发起它的那一代表单；响应再晚返回，只要用户已经离开
533	    // （首页/详情/编辑切换、重新进入同一问卷、浏览器前进后退），其成功或
534	    // 失败结果都必须静默丢弃，不能跳转、清空或提示到当前页面上。
535	    const submitView = view;
536	    let resp;
537	    try {
538	      resp = await fetch(endpoint, {
539	        method: creating ? "POST" : "PUT",
540	        headers: {"Content-Type": "application/json"},
541	        body: JSON.stringify(payload)
542	      });
543	    } catch (err) {
544	      if (submitView !== activeView) return;
545	      // 请求未成功：结束等待，保留当前全部输入与增删结果。新建模式下编号仍未
546	      // 拿到（surveyId 保持 null），修改后再次保存会重新 POST 创建，绝不会
547	      // 显示成功或跳进某份问卷详情。
548	      saving = false;
549	      resetSaveButton();
550	      hideSaveStatus();
551	      showBanner([{el: null, msg: creating
552	        ? `网络错误，本次创建尚未确认保存：${err}。已填写的内容仍保留在页面上，修改后可重新创建。`
553	        : `网络错误，问卷尚未保存：${err}`}]);
554	      return;
555	    }
556	    if (submitView !== activeView) return;
557	    let data = {};
558	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
559	    if (submitView !== activeView) return;
560	    const saved = creating ? resp.status === 201 : resp.status === 200;
561	    if (saved && data.id !== undefined) {
562	      if (creating) {
563	        // 首次创建成功：这份表单从此绑定到刚创建的编号。刷新首页列表，让新
564	        // 草稿出现在列表中；列表与详情使用同一个编号。
565	        surveyId = data.id;
566	        if (hooks && hooks.onCreated) hooks.onCreated();
567	      }
568	      // 先把“这次提交的内容”记为已保存（服务器上的草稿正是它）。
569	      if (hooks && hooks.markSaved) hooks.markSaved(submittedState);
570	      // 比较点击保存前后的整份表单：等待期间改过又恢复原值时结构相同，按
571	      // 无新改动处理，仍进入详情。
572	      const stillSame = hooks && hooks.isCurrent ? hooks.isCurrent(submittedState) : true;
573	      if (stillSame) {
574	        if (creating) {
575	          // 新建且等待期间没有新改动：沿用原有行为，清空新建表单并进入新问卷
576	          // 详情，详情展示的就是服务器实际保存的内容。
577	          form.reset();
578	          qBox.replaceChildren();
579	          autoGrow(titleInput);
580	        }
581	        location.hash = `#/surveys/${data.id}`;
582	        return;
583	      }
584	      // 等待期间出现了新的修改：不跳转，保留当前完整内容与顺序（题目与选项
585	      // 维持页面当前次序，不恢复成提交时的结构）。绿色块只确认“刚才提交的
586	      // 内容已保存”，黄色块提示“当前还有未保存的修改”，不自动补交，也不
587	      // 撤销已成功的保存。新建表单就此转为编辑刚创建的那份草稿：标题改为
588	      // 编辑态、补上“取消”链接、按钮文案改为“保存修改”；再次点击保存时
589	      // surveyId 已存在，走 PUT 同一编号，提交的才是当前内容。
590	      if (creating) adoptCreatedDraft(data.id);
591	      saving = false;
592	      resetSaveButton();
593	      renderSaveStatus(true);
594	      return;
595	    }
596	    // 服务端未确认保存成功：结束等待，不清空任何输入，展示具体问题；用户修改
597	    // 后可再次保存（不会自行重发，也不会一直停在“正在保存”）。新建模式下
598	    // 本次没有创建任何记录（surveyId 仍为 null），再次保存仍是重新创建。
599	    saving = false;
600	    resetSaveButton();
601	    hideSaveStatus();
602	    showBanner([{el: null, msg: data.error
603	      || (creating
