789	def contains_unpaired_surrogate(text):
790	    """True if text holds an unpaired UTF-16 surrogate code point (U+D800..U+DFFF).
791	
792	    A syntactically legal JSON body can still contain one via an unpaired
793	    ``\\uD800``/``\\uDC00`` escape. Such a code point cannot be encoded as
794	    UTF-8, so it must be rejected as a content error of the specific field
795	    before saving: otherwise encoding the response later aborts the request
796	    without returning the validation result the caller expects. Correctly
797	    paired escapes decode to a single astral character (e.g. an emoji) and
798	    never match this check.
799	    """
800	    return any(0xD800 <= ord(ch) <= 0xDFFF for ch in text)
